{"content": """"
Minimal Auth module for Arsify MoE Router.
Provides require_auth, require_admin, and API key management.
"""

from fastapi import HTTPException, Security, Depends
from fastapi.security import APIKeyHeader
from config import settings
import json, os

API_KEY_HEADER = APIKeyHeader(name="X-API-Key", auto_error=False)

# In-memory key store (persisted to file if path set)
_keys_db = {}


def _load_keys():
    global _keys_db
    if os.path.exists(settings.KEYS_FILE):
        try:
            with open(settings.KEYS_FILE, "r") as f:
                _keys_db = json.load(f)
        except Exception:
            _keys_db = {}
    else:
        # Default: create a master key if none exists
        from config import generate_api_key
        master = settings.MASTER_KEY or generate_api_key("mk")
        _keys_db = {
            master: {"name": "master", "role": "admin", "rate_limit": 9999, "monthly_quota": 999999}
        }
        _save_keys()


def _save_keys():
    try:
        with open(settings.KEYS_FILE, "w") as f:
            json.dump(_keys_db, f, indent=2)
    except Exception:
        pass


_load_keys()


async def require_auth(api_key: str = Security(API_KEY_HEADER)):
    if not settings.AUTH_ENABLED:
        return {"role": "admin", "name": "auth_disabled"}
    if not api_key or api_key not in _keys_db:
        raise HTTPException(status_code=401, detail="Invalid or missing API key")
    return _keys_db[api_key]


async def require_admin(key_data: dict = Depends(require_auth)):
    if key_data.get("role") != "admin":
        raise HTTPException(status_code=403, detail="Admin access required")
    return key_data


def create_key(name: str, role: str = "user", rate_limit: int = 60, monthly_quota: int = 10000, expires_at: str = None):
    from config import generate_api_key
    key = generate_api_key()
    _keys_db[key] = {
        "name": name,
        "role": role,
        "rate_limit": rate_limit,
        "monthly_quota": monthly_quota,
        "expires_at": expires_at,
    }
    _save_keys()
    return {"key": key, "detail": _keys_db[key]}


def list_keys():
    return [{"key": k[:8] + "...", "name": v["name"], "role": v["role"]} for k, v in _keys_db.items()]


def revoke_key(key: str) -> bool:
    if key in _keys_db:
        del _keys_db[key]
        _save_keys()
        return True
    return False
